('jq-0026-1','math','初中',7,'jkp-0026','single_choice',0.45,'边长为 8 的正方形周长用字母表示：C = 4a，当 a=8 时 C=？','[{"key": "A", "text": "32"}, {"key": "B", "text": "8"}, {"key": "C", "text": "64"}, {"key": "D", "text": "16"}]','A','C=4a=4×8=32','template-j','approved','通用');
