('jq-0035-1','math','初中',7,'jkp-0035','single_choice',0.35,'化简求值：当 x=4 时，2x² + x² = ？','[{"key": "A", "text": "48"}, {"key": "B", "text": "32"}, {"key": "C", "text": "12"}, {"key": "D", "text": "20"}]','A','2x²+x²=3x²，x=4 时 3×4²=48','template-j','approved','通用');